/****************************************************************************
 * Name: rk3576_vop_store_pixel
 *
 * Description:
 *   Write one RGB888 pixel, 0xRRGGBB, at a byte address in the framebuffer.
 *
 *   The whole framebuffer is addressed this way: a row starts at
 *   y * priv->stride, not at y * xres * 3, because a row is padded up to a
 *   whole 32-bit word.  Anything that walks the buffer three bytes at a time
 *   across a row boundary writes pixels that the ESMART never fetches, and
 *   every row after the first then starts on the wrong byte of the colour.
 *
 ****************************************************************************/

static void rk3576_vop_store_pixel(FAR uint8_t *px, uint32_t rgb)
{
  px[0] = (uint8_t)(rgb >> 16);
  px[1] = (uint8_t)(rgb >> 8);
  px[2] = (uint8_t)rgb;
}

