      uint32_t stride = pitch(xres);
      size_t fblen = (size_t)stride * yres;
      uint8_t *old = malloc(fblen), *new = malloc(fblen);
      uint32_t y, x; size_t n; int wrong_old = 0, oob_old = 0;

      memset(old, 0, fblen); memset(new, 0, fblen);

      /* old: contiguous 3-byte sweep, guarded at fblen */
      for (n = 0; n + BPP <= fblen; n += BPP)
        { old[n+0]=0xff; old[n+1]=0x00; old[n+2]=0xff; }   /* purple */

      /* new: row by row, xres pixels */
      for (y = 0; y < yres; y++)
        for (x = 0; x < xres; x++)
