            if (new[o]!=0xff||new[o+1]!=0x00||new[o+2]!=0xff) wrong_old |= 4; }

      /* old row-head colours */
      for (y = 0; y < yres; y++)
        { size_t o = (size_t)y*stride;
          if (old[o]!=0xff||old[o+1]!=0x00||old[o+2]!=0xff) wrong_old |= 1; }

